#include <stdio.h>
#include <string.h>

int main() {
    char n[1005];
    int m;

    scanf("%s", n);
    scanf("%d", &m);

    int lenN = strlen(n);
    int count = 0;

    char map[26];
    char keys[8][5] = {
        "abc", "def", "ghi", "jkl",
        "mno", "pqrs", "tuv", "wxyz"
    };

    for (int i = 0; i < 8; i++) {
        for (int j = 0; keys[i][j] != '\0'; j++) {
            map[keys[i][j] - 'a'] = '2' + i;
        }
    }

    for (int i = 0; i < m; i++) {
        char s[1005];
        scanf("%s", s);

        if ((int)strlen(s) != lenN) continue;

        int ok = 1;
        for (int j = 0; j < lenN; j++) {
            if (map[s[j] - 'a'] != n[j]) {
                ok = 0;
                break;
            }
        }

        if (ok) count++;
    }

    printf("%d\n", count);

    return 0;
}
